#include <bits/stdc++.h>
using namespace std;
const long long MOD = 1000000007;
string s;
vector<long long> memo;
long long decode(int i) {  // decodings of s[i..]
    if (i == (int)s.size()) return 1;
    if (s[i] == '0') return 0;
    if (memo[i] != -1) return memo[i];
    long long total = decode(i + 1);
    if (i + 1 < (int)s.size() && (s[i] - '0') * 10 + (s[i + 1] - '0') <= 26) total += decode(i + 2);
    return memo[i] = total % MOD;
}
int main() {
    cin >> s;
    memo.assign(s.size(), -1);
    cout << decode(0) << "\n";
    return 0;
}

